BEGIN;
CREATE FUNCTION encova_finance_report_metadata(date_from DATE,date_to DATE,filters JSONB) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('company',coalesce((SELECT "companyName" FROM public."CompanySettings" ORDER BY id LIMIT 1),'Encova Solutions'),'currency','PKR','basis','POSTED_ACCRUAL','timezone','Asia/Karachi','from',date_from,'to',date_to,'filters',filters,'generatedAt',statement_timestamp(),'databaseSnapshot',pg_current_snapshot()::text,'postingCutoffAt',max(e."postedAt"),'postedEntryCount',count(*),'ledgerDigest',encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',e.id,'date',e."postingDate",'postedAt',e."postedAt") ORDER BY e.id),'[]'::jsonb)::text,'UTF8')),'hex')) FROM public."FinanceJournalEntry" e WHERE e."postingDate"<=date_to
$$;
CREATE FUNCTION encova_finance_report_ledger(account_id UUID,date_from DATE,date_to DATE,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE account public."FinanceAccount"%ROWTYPE;opening NUMERIC;period_debit NUMERIC;period_credit NUMERIC;total INTEGER;page INTEGER;pages INTEGER;items JSONB;BEGIN
 SELECT * INTO account FROM public."FinanceAccount" WHERE id=account_id AND "isPosting" AND currency='PKR';IF account.id IS NULL THEN RAISE EXCEPTION 'FINANCE_ACCOUNT_UNAVAILABLE' USING ERRCODE='P0001';END IF;
 SELECT coalesce(sum(l.debit-l.credit) FILTER(WHERE e."postingDate"<date_from),0),coalesce(sum(l.debit) FILTER(WHERE e."postingDate">=date_from),0),coalesce(sum(l.credit) FILTER(WHERE e."postingDate">=date_from),0),count(*) FILTER(WHERE e."postingDate">=date_from) INTO opening,period_debit,period_credit,total FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=account.id AND e."postingDate"<=date_to;
 pages:=greatest(1,ceil(total/25.0)::integer);page:=least(requested_page,pages);
 WITH movements AS(SELECT l.id,l.sequence,e.id AS "journalId",e."postingDate",e.reference,e."sourceType",e."sourceId",e."sourceAction",e."reversalOfId",l.description,l.debit::text AS debit,l.credit::text AS credit,l."projectId",p.name AS "projectName",l."partyId",party.name AS "partyName",round(opening+sum(l.debit-l.credit) OVER(ORDER BY e."postingDate",e.id,l.sequence,l.id ROWS UNBOUNDED PRECEDING),2)::text AS "runningBalance" FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" LEFT JOIN public."Project" p ON p.id=l."projectId" LEFT JOIN public."FinanceParty" party ON party.id=l."partyId" WHERE l."accountId"=account.id AND e."postingDate" BETWEEN date_from AND date_to),bounded AS(SELECT * FROM movements ORDER BY "postingDate","journalId",sequence,id LIMIT 25 OFFSET(page-1)*25)
 SELECT coalesce(jsonb_agg(to_jsonb(bounded) ORDER BY "postingDate","journalId",sequence,id),'[]'::jsonb) INTO items FROM bounded;
 RETURN jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,date_to,jsonb_build_object('report','GENERAL_LEDGER','accountId',account.id)),'account',jsonb_build_object('id',account.id,'code',account.code,'name',account.name,'type',account.type,'normalSide',account."normalSide",'controlType',account."controlType",'active',account.active),'openingBalance',round(opening,2)::text,'periodDebit',round(period_debit,2)::text,'periodCredit',round(period_credit,2)::text,'closingBalance',round(opening+period_debit-period_credit,2)::text,'items',items,'total',total,'page',page,'pages',pages);
END $$;
CREATE FUNCTION encova_finance_report_trial(date_from DATE,date_to DATE,search TEXT,include_zero BOOLEAN,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result JSONB;BEGIN
 WITH balances AS MATERIALIZED(SELECT a.id,a.code,a.name,a.type,a."normalSide",a."controlType",a.active,coalesce(sum(l.debit-l.credit) FILTER(WHERE e."postingDate"<date_from),0) AS opening,coalesce(sum(l.debit) FILTER(WHERE e."postingDate">=date_from),0) AS debit,coalesce(sum(l.credit) FILTER(WHERE e."postingDate">=date_from),0) AS credit FROM public."FinanceAccount" a LEFT JOIN(public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" AND e."postingDate"<=date_to) ON l."accountId"=a.id WHERE a."isPosting" AND a.currency='PKR' GROUP BY a.id),
 complete AS(SELECT *,opening+debit-credit AS closing FROM balances),totals AS(SELECT jsonb_build_object('openingDebit',round(coalesce(sum(greatest(opening,0)),0),2)::text,'openingCredit',round(coalesce(sum(greatest(-opening,0)),0),2)::text,'periodDebit',round(coalesce(sum(debit),0),2)::text,'periodCredit',round(coalesce(sum(credit),0),2)::text,'closingDebit',round(coalesce(sum(greatest(closing,0)),0),2)::text,'closingCredit',round(coalesce(sum(greatest(-closing,0)),0),2)::text,'openingDifference',round(coalesce(sum(opening),0),2)::text,'periodDifference',round(coalesce(sum(debit-credit),0),2)::text,'closingDifference',round(coalesce(sum(closing),0),2)::text,'accountCount',count(*)) AS data FROM complete),
 displayed AS MATERIALIZED(SELECT * FROM complete WHERE concat_ws(' ',code,name) ILIKE '%'||search||'%' AND(include_zero OR opening<>0 OR debit<>0 OR credit<>0)),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM displayed),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT d.* FROM displayed d ORDER BY d.code,d.id LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),
 rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type,'normalSide',"normalSide",'controlType',"controlType",'active',active,'openingBalance',round(opening,2)::text,'openingDebit',round(greatest(opening,0),2)::text,'openingCredit',round(greatest(-opening,0),2)::text,'periodDebit',round(debit,2)::text,'periodCredit',round(credit,2)::text,'closingBalance',round(closing,2)::text,'closingDebit',round(greatest(closing,0),2)::text,'closingCredit',round(greatest(-closing,0),2)::text) ORDER BY code,id),'[]'::jsonb) AS items FROM bounded)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,date_to,jsonb_build_object('report','TRIAL_BALANCE','displaySearch',search,'includeZero',include_zero)),'companyTotals',totals.data,'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM totals CROSS JOIN paging CROSS JOIN rows;
 RETURN result;
END $$;
CREATE FUNCTION encova_finance_report_core(actor UUID,kind TEXT,input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE date_from DATE;date_to DATE;requested_page INTEGER;search TEXT;items JSONB;total INTEGER;page INTEGER;pages INTEGER;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 IF kind IS NULL OR kind NOT IN('GENERAL_LEDGER','TRIAL_BALANCE','ACCOUNT_OPTIONS') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR jsonb_typeof(input->'page') IS DISTINCT FROM 'number' OR(input->>'page')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 requested_page:=(input->>'page')::integer;
 IF kind='ACCOUNT_OPTIONS' THEN
  IF input-ARRAY['q','page']<>'{}'::jsonb OR jsonb_typeof(input->'q') IS DISTINCT FROM 'string' OR length(input->>'q')>100 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  search:=input->>'q';SELECT count(*) INTO total FROM public."FinanceAccount" WHERE "isPosting" AND currency='PKR' AND concat_ws(' ',code,name) ILIKE '%'||search||'%';pages:=greatest(1,ceil(total/25.0)::integer);page:=least(requested_page,pages);
  SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.code,b.id),'[]'::jsonb) INTO items FROM(SELECT id,code,name,active,"controlType" FROM public."FinanceAccount" WHERE "isPosting" AND currency='PKR' AND concat_ws(' ',code,name) ILIKE '%'||search||'%' ORDER BY code,id LIMIT 25 OFFSET(page-1)*25)b;RETURN jsonb_build_object('items',items,'total',total,'page',page,'pages',pages);
 END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['from','to'])k WHERE jsonb_typeof(input->k) IS DISTINCT FROM 'string') OR input->>'from'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'to'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 date_from:=(input->>'from')::date;date_to:=(input->>'to')::date;IF date_from<DATE '0001-01-01' OR date_to>DATE '9999-12-31' OR date_from>date_to THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF kind='GENERAL_LEDGER' THEN
  IF input-ARRAY['from','to','accountId','page']<>'{}'::jsonb OR jsonb_typeof(input->'accountId') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  RETURN public.encova_finance_report_ledger((input->>'accountId')::uuid,date_from,date_to,requested_page);
 END IF;
 IF input-ARRAY['from','to','q','includeZero','page']<>'{}'::jsonb OR jsonb_typeof(input->'q') IS DISTINCT FROM 'string' OR length(input->>'q')>100 OR input->>'includeZero' IS NULL OR input->>'includeZero' NOT IN('YES','NO') THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 RETURN public.encova_finance_report_trial(date_from,date_to,input->>'q',input->>'includeZero'='YES',requested_page);
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
DO $$ DECLARE f RECORD;r TEXT;BEGIN
 FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'encova_finance_report_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);FOREACH r IN ARRAY ARRAY['encova_app','anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r);END IF;END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION public.encova_finance_report_core(UUID,TEXT,JSONB) TO encova_app;END IF;
END $$;
COMMIT;
